let frozenHashes: Record<string,string> | undefined;
function baselineHashes() {
  if(frozenHashes)return frozenHashes;
  const paths=git('ls-tree','-r','--name-only',baselineHead,'--','docs/data/complete-edition','docs/reports/complete-edition').split(/\r?\n/).filter(p=>/\/c1c(?:20|21|22|23|24)-/.test(p));
  const bytes=execFileSync('git',['cat-file','--batch'],{input:paths.map(p=>baselineHead+':'+p).join('\n')+'\n',maxBuffer:128*1024*1024});
  let cursor=0;frozenHashes={};
  for(const path of paths){const end=bytes.indexOf(10,cursor),header=bytes.subarray(cursor,end).toString(),size=Number(header.split(' ').at(-1));assert(Number.isFinite(size),'baseline blob');cursor=end+1;frozenHashes[path]=sha256(bytes.subarray(cursor,cursor+size));cursor+=size+1;}
  return frozenHashes;
}
const printed = (d:any, side:string, literal:string) => ({kind:'PRINTED_COMPONENT',physicalIdentity:d.physicalIdentity,definitionId:d.definitionId,side,literal,path:d.sourceReferences.find((s:any)=>s.side===side).path,sha256:d.sourceReferences.find((s:any)=>s.side===side).cropSha256});
export function unresolvedLeaves(value:any, path=''): any[] {
  if (!value || typeof value!=='object') return [];
  if (value.status==='SOURCE_UNRESOLVED') return [{field:path,category:value.category,reason:value.reason,sourceReferences:value.sourceReferences}];
  return Object.entries(value).flatMap(([key,child])=>unresolvedLeaves(child,path+'/'+key));
}
export function decide(capability:any, roi:any) {
  const eligible = capability.family.semanticComplete===9 && capability.family.executionBlockers===0 && roi.family.sourceFoundationEligible;
  return {selectedFamily:'Necromancer',outcome:eligible?'NECROMANCER_RUNTIME_FOUNDATION_SELECTED':'NECROMANCER_SOURCE_CLOSURE_CONTINUATION',
    verdict:eligible?'NEXT-NECROMANCER-RUNTIME-FOUNDATION-SELECTED':'NEXT-NECROMANCER-SOURCE-CLOSURE-CONTINUATION',
    runtimeFoundationSelected:eligible,expectedProductionReadyGain:0,
    sourceBlockerCategories:capability.family.sourceBlockerCategories,terminalBlockersProven:false,
    reason:eligible?'All execution source gates closed.':'Bounded source leaves remain; unavailable FAQ access does not establish terminal impossibility. Keep this family and close these leaves before gameplay.',
    c1c26:eligible?'Necromancer Runtime Foundation':'Necromancer Source Closure Continuation'};
}

