export function validateArtifacts(actual:Record<string,any>) {
  const expected=buildArtifacts();
  assert(JSON.stringify(Object.keys(actual).sort())===JSON.stringify(Object.keys(expected).sort()),'artifact set drift');
  for(const [name,body] of Object.entries(expected)) assert(JSON.stringify(actual[name])===JSON.stringify(body),'source-derived artifact drift: '+name);
  const defs=actual['c1c25-necromancer-card-semantic-contracts.json'].cards;
  assert(defs.every((d:any)=>!d.semanticComplete||unresolvedLeaves(d).length===0),'unresolved source cannot promote semantics');
  const reg=actual['c1c25-necromancer-source-gap-register.json'].sourceGaps;
  const sourceArtifacts=Object.entries(actual).filter(([name])=>!/(source-gap-register|runtime-capability|family-completeness|runtime-roi|next-workstream|source-manifest)\.json$/.test(name));
  const leaves=sourceArtifacts.flatMap(([artifact,body])=>unresolvedLeaves(body).map(g=>artifact+':'+g.field));
  assert(JSON.stringify(leaves.sort())===JSON.stringify(reg.map((g:any)=>g.gapId).sort()),'all unresolved leaves registered');
}
export async function verifyAssets() {
  const ext=load('c1c25-external-source-manifest.json'), raw=load('complete-edition-raw-inventory.json');
  const ttsMeta=load('c1c24-boss-crop-manifest.json').ttsSource;
  const ttsBytes=readFileSync(ttsMeta.path);assert(sha256(ttsBytes)===ttsMeta.sha256,'locked original TTS hash');
  const tts=JSON.parse(ttsBytes.toString());
  for(const a of ext.assets) {
    const bytes=readFileSync(a.path), decoded=await sharp(bytes).metadata();
    assert(sha256(bytes)===a.sha256 && createHash('sha1').update(bytes).digest('hex')===a.sha1,'external sheet bytes');
    assert(a.sha1.toUpperCase()===a.url.split('/').filter(Boolean).at(-1),'original URL content hash');
    assert(decoded.width===a.width&&decoded.height===a.height&&bytes.length===a.byteLength,'external sheet geometry');
    const receipt=JSON.parse(readFileSync(a.path+'.receipt.json','utf8'));assert(receipt.acquiredAt===a.acquiredAt&&receipt.acquisitionKind===a.acquisitionKind,'external receipt');
  }
  for(const b of ext.bindings) {
    const o=raw.objects.find((o:any)=>o.physicalIdentity===b.physicalIdentity);
    const original=b.ttsPath.split('/').filter(Boolean).reduce((v:any,k:string)=>v[k],tts);
    assert(o&&original.GUID===b.sourceObjectGuid&&original.CardID===b.cardId,'external physical path');
    const deck=original.CustomDeck[o.deckId];
    for(const side of ['front','back']) {
      const s=b[side],url=side==='front'?o.faceUrl:o.backUrl;
      assert(s.url===url&&s.url===(side==='front'?deck.FaceURL:deck.BackURL),'external source URL');
      const a=ext.assets.find((a:any)=>a.url===url), gw=side==='back'&&!o.uniqueBack?1:o.numWidth,gh=side==='back'&&!o.uniqueBack?1:o.numHeight,cell=gw===1&&gh===1?0:o.cardIndex;
      const col=cell%gw,row=Math.floor(cell/gw),left=Math.floor(col*a.width/gw),top=Math.floor(row*a.height/gh);
      const bounds={left,top,width:Math.floor((col+1)*a.width/gw)-left,height:Math.floor((row+1)*a.height/gh)-top};
      assert(s.cell===cell&&s.grid.width===gw&&s.grid.height===gh&&JSON.stringify(s.bounds)===JSON.stringify(bounds),'external sheet/cell');
      assert(s.path===root+'source-assets/c1c25/crops/'+b.cardId+'-'+sha256(b.physicalIdentity).slice(0,12)+'-'+side+'.png','canonical external crop');
      assert(hash(s.path)===s.sha256&&sha256(await sharp(a.path).extract(bounds).png().toBuffer())===s.sha256,'byte-rebuilt external crop');
    }
  }
  const tile=ext.tile, tileRaw=tile.ttsPath.split('/').filter(Boolean).reduce((v:any,k:string)=>v[k],tts);
  assert(tileRaw.CustomImage.ImageSecondaryURL===tile.url&&tileRaw.GUID===tile.sourceObjectGuid&&hash(tile.path)===tile.sha256,'Room Tile original path/side/bytes');
  for(const d of locked())for(const s of d.sourceReferences) assert(hash(s.path)===s.cropSha256,'locked core literal crop');
}
export function verifyScope(paths:string[]) {
  const allowed=(p:string)=>p==='package.json'||/^scripts\/audit\/(?:c1c25-contract\.ts|(?:generate|verify)-complete-edition-c1c25\.ts|acquire-c1c25-sources\.mjs)$/.test(p)||p==='src/audit/c1c25-necromancer-semantic-source-intake.test.ts'||/^docs\/(?:data|reports)\/complete-edition\/c1c25-/.test(p)||p.startsWith(root+'source-assets/c1c25/');
  assert(paths.every(allowed),'audit-only scope violated: gameplay / UI / Act IV / upstream frozen');
}
export function report(a=buildArtifacts()) {
  const f=a['c1c25-necromancer-runtime-capability-matrix.json'].family;
  return `# C1C25 Necromancer semantic source intake\n\nVerdict: C1C25-NECROMANCER-SEMANTIC-SOURCE-INTAKE-ACCEPTED\n\nBaseline: ${baselineHead}, codex/phase-11a4-c1c24-boss-source-intake. This accepts the reproducible intake and source gaps, not completed execution semantics.\n\n## Nine locked core cards\n\nPhysical 9; literalComplete 9; semanticComplete ${f.semanticComplete}; sourceGated ${f.sourceGated}; runtimeCandidate 0; Production Ready 0. Three narrative identity cards have card-local selection semantics; family execution dependencies prevent promoting them. No external component changes the C1C24 census.\n\n| Level | Identity card | Threat / Ability physical card | Battle card | Printed Life | Named summon / printed monster level |\n|---|---:|---:|---:|---:|---|\n| I | 42000 | 42003 | 46037 | 77 | Bone Rabble / I |\n| II | 42001 | 42004 | 46038 | 103 | Bone Soldier / I |\n| III | 42002 | 42005 | 46039 | 144 | Bone Spearman / II |\n\nLevel links have printed, same-container and core p11/p30 evidence. Core composition is source-bound at every level; full encounter composition remains gated on finite summon copy/exhaustion policy. Stats are on Battle cards, not narrative Identity cards. No campaign-level default is applied to Bone cards.\n\n## Threat and Ability\n\nCore p11/p30 and printed clauses bind Hamlet/Dungeon triggers. Both passives cease immediately when the physical card flips to Ability upon entering the Boss Objective Room. This is an explicitly sourced physical flip; Threat and Ability are not simultaneous. One action per round is printed, with no Boss flee round limit (p30). Level I permanently removed monsters remain removed after passive expiry. Level II Army of the Dead is a first-Battle Bone Captain spawn; Level III Reanimation is immediate first non-large death per Battle with no-space suppression. The latter still needs casualty/initiative ordering clarification. Threat trigger and expiry are closed; no fabricated round-end expiry or battle Threat draw deck.\n\n## Targeting and Skill effects\n\nAll three Skills use Crowded Area targeting, with target counts 2 / 2 / 4. Range is 1 / 2 / 2; skill D10 table is 1-3 / 4-6 / 7-10 in all Stances. Core p19/p20/p24 bind one attack roll with per-Hero Dodge comparisons, Self Push 1 after the roll even on a miss, then damage and successful Target effects. Multi-target summon count remains unresolved. p24 Stance priority is retained for monster character targeting; tied Crowded Areas need an explicit Area rule.\n\nHaunted Graveyard / The Restless Dead lowest-roll Hero ties remain LOWEST_ROLL_HERO_TIE_UNRESOLVED. Monster targeting text does not establish a Hamlet die tie rule. No random, active-Hero, first-player or player-choice fallback is adopted.\n\n## Bone identities and discrepancy\n\nOriginal source sheets/cells independently bind Bone Rabble, Soldier, Spearman, Courtier, Defender and Captain. Only Rabble / Soldier / Spearman are named by Boss Skills; Courtier / Defender are not added to the summon roster. Bone Captain is a separate Level II Dungeon Threat dependency; its full Large combat card and narrow artwork component are not merged as copies. Bone Rubble is not found as a printed monster name in this acquired set. Printed Bone Rabble versus core p38 Bone Rubble remains UNRESOLVED / SOURCE_PRECEDENCE_UNRESOLVED; TTS naming agreement is corroboration, not erratum authority. Candidate component counts are observations, not infinite summon supply or invented reuse rules.\n\n## Full Stance, Room and setup\n\nFull-Stance precedence is closed by explicit scope: the printed Boss Ability suppresses summoning when all Stances are occupied, p38 uses first empty Stance, p31 displaces miniatures for Room Area space, and p17 handles a large-Monster initial draw. No generic full-Stance replacement is inferred. Nearest-available-Area tie / nowhere-available fallback remains a source gap.\n\nRoom Card 44709 is 10—Necromancer Room. Exact tile object 51494f (10-11) uses ImageSecondaryURL, which visibly prints 10; the primary side prints 11 and is not the Necromancer side. Eight visually annotated Areas have capacities 3 / 4 / 3 / 4 / 2 / 2 / 2 / 4. All Hero Stances start in the lower central Area; Boss Aggressive starts in the upper central high-ground Area. Named summons go to the Skill Target Area. Room identity, layout and starting locations are bound for all levels; no Room-specific functional text is printed beyond BOSS. Setup contracts use p16/p30/p38, and cleanup ends the Battle, removes summons and advances Campaign Level / Act. Exact post-defeat destinations of the Boss trio remain unresolved.\n\n## Capability and C1C26\n\nExternal dependencies BOUND ${f.externalDependenciesResolved}/${f.externalDependenciesTotal} (one Quest dependency remains explicitly OUT_OF_SCOPE). ${f.executionBlockers} unresolved usages across ${f.sourceBlockerCategories.length} execution source topics are registered with null values and evidence. All nine cards remain family source gated. Existing Necromancer prototype and position-based AI are audited as insufficient consumers of these contracts; no gameplay code is changed. Whole-family ROI yields NECROMANCER_SOURCE_CLOSURE_CONTINUATION / NEXT-NECROMANCER-SOURCE-CLOSURE-CONTINUATION. C1C26 Necromancer Runtime Foundation is NOT allowed.\n\nThe next closure targets are: ${f.sourceBlockerCategories.join(', ')}. They are bounded questions; failure to access the designer FAQ is not proof of terminal source impossibility, so no other family is selected. The search evidence records exact queries, the [designer FAQ listing](https://boardgamegeek.com/boardgame/317321/darkest-dungeon-the-board-game/files), inaccessible authoritative content and rejected secondary candidates; no online community mechanics become rules.\n\n## Frozen regressions and validation\n\nC1C20 Core Trinket 15/37 Ready; C1C21 Standard Quest 3/75; C1C22 census 278; C1C23 Hamlet Event 16 literal / 5 card-local semantic / 0 Ready; C1C24 ordinary Boss 231 / 20 families and Battle 114 / Threat 51 / exclusive Ability 12 / Identity 54 remain byte-frozen. Other Boss families, Battle engine, UI, selector, save/replay and Act IV are unchanged.\n\nC1C13/C1C12/C1C11 reload retry exhaustion and C1C3 selector click timeout remain open. Complete Edition browser E2E is not fully accepted. See c1c25-validation-report.md for actual verification results.\n`;
}
